    actionId: string
    actionName: string
    command: string | null
    message: string
    phase: ActionRunPhase
    permissionMode?: PermissionMode
    status: ActionRunStatus
    stderr: string
    stdout: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionRunResult {
